window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_mathematics_de"]=window.LC_CHUNKS["university_mathematics_de"]||{};window.LC_CHUNKS["university_mathematics_de"][11]={"university_mathematics_de:M11-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M11-L1 – Totale Ableitung, Jacobi-Matrix und Umkehrsatz<\/h1>\n<p><strong>Kursbereich:<\/strong> M11 – Analysis, lineare Algebra und Wahrscheinlichkeit vertieft<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Studiengrundlagen und\nVertiefung<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor Analysis-Kern/Vertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du unterscheidest partielle und totale Differenzierbarkeit,\nberechnest die Jacobi-Matrix und die Ableitung einer Verkettung, wendest\nden lokalen Umkehrsatz an und prüfst seine Voraussetzungen an\nGegenbeispielen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lineare Näherung und Restterm<\/h2>\n<p>Die in <a href=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4<\/a> eingeführten\npartiellen Ableitungen beschreiben Änderungen entlang einzelner\nKoordinaten. Die totale Ableitung erfasst gleichzeitig beliebige kleine\nÄnderungen. Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>⊂<\/mo><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mi>n<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">U\\subset\\mathbb R^n<\/annotation><\/semantics><\/math>\noffen und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>:<\/mo><mi>U<\/mi><mo>→<\/mo><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mi>m<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f:U\\to\\mathbb R^m<\/annotation><\/semantics><\/math>.\nIn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>∈<\/mo><mi>U<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a\\in U<\/annotation><\/semantics><\/math>\nheißt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\ntotal differenzierbar, wenn eine lineare Abbildung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nexistiert mit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>A<\/mi><mi>h<\/mi><mo>+<\/mo><mi>r<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><munder><mi mathvariant=\"normal\">lim<\/mi><mrow><mi>h<\/mi><mo>→<\/mo><mn>0<\/mn><mo>,<\/mo><mi>h<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><\/munder><mfrac><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>r<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><\/mfrac><mo>=<\/mo><mn>0<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f(a+h)=f(a)+Ah+r(h),\\qquad \\lim_{h\\to0,h\\ne0}\\frac{\\|r(h)\\|}{\\|h\\|}=0.<\/annotation><\/semantics><\/math><\/p>\n<p>Die Norm sei euklidisch. Die Abbildung ist eindeutig: Sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>,<\/mo><mi>B<\/mi><\/mrow><annotation encoding=\"application/x-tex\">A,B<\/annotation><\/semantics><\/math>\nzulässig, folgt für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mi>t<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">h=tv<\/annotation><\/semantics><\/math>\nnach Division durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|t|<\/annotation><\/semantics><\/math>\nund Grenzübergang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>A<\/mi><mo>−<\/mo><mi>B<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>v<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(A-B)v=0<\/annotation><\/semantics><\/math>\nfür jeden Vektor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>v<\/mi><annotation encoding=\"application/x-tex\">v<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mi>t<\/mi><msub><mi>e<\/mi><mi>j<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">h=te_j<\/annotation><\/semantics><\/math>\nfolgt aus dem Restterm, dass die\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>j<\/mi><annotation encoding=\"application/x-tex\">j<\/annotation><\/semantics><\/math>-te\nSpalte von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\ndie partiellen Ableitungen in Richtung der\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>j<\/mi><annotation encoding=\"application/x-tex\">j<\/annotation><\/semantics><\/math>-ten\nKoordinate enthält. Somit gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mi>D<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>J<\/mi><mi>f<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>∂<\/mi><mi>j<\/mi><\/msub><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi>i<\/mi><mo>,<\/mo><mi>j<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">A=Df(a)=J_f(a)=(\\partial_j f_i(a))_{i,j}<\/annotation><\/semantics><\/math>,\neine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>×<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\times n<\/annotation><\/semantics><\/math>-Matrix.\nStetige partielle Ableitungen in einer offenen Umgebung sind\nhinreichend: Entlang der Strecke von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a<\/mi><annotation encoding=\"application/x-tex\">a<\/annotation><\/semantics><\/math>\nnach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>+<\/mo><mi>h<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a+h<\/annotation><\/semantics><\/math>\nliefert der Hauptsatz komponentenweise den Rest\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>0<\/mn><mn>1<\/mn><\/msubsup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>J<\/mi><mi>f<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mi>t<\/mi><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msub><mi>J<\/mi><mi>f<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>h<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_0^1 (J_f(a+th)-J_f(a))h\\,dt<\/annotation><\/semantics><\/math>.\nSeine Norm geteilt durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\|h\\|<\/annotation><\/semantics><\/math>\ngeht wegen Stetigkeit gegen null. Die Strecke liegt für kleine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\nvollständig in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>U<\/mi><annotation encoding=\"application/x-tex\">U<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Beispiel, Kettenregel und Gegenbeispiel<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><mo>,<\/mo><mn>2<\/mn><mi>y<\/mi><mo>+<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(x,y)=(x+y^2,2y+x)<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J<\/mi><mi>f<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><mi>y<\/mi><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">J_f(x,y)=\\begin{pmatrix}1&amp;2y\\\\1&amp;2\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">a=(0,0)<\/annotation><\/semantics><\/math>\nergibt sich für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">h=(s,t)<\/annotation><\/semantics><\/math>\nexakt der Rest\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>t<\/mi><mn>2<\/mn><\/msup><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(t^2,0)<\/annotation><\/semantics><\/math>;\nder normierte Rest ist höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\|h\\|<\/annotation><\/semantics><\/math>.\nFür eine differenzierbare Folgeabbildung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>g<\/mi><annotation encoding=\"application/x-tex\">g<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>g<\/mi><mo>∘<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>D<\/mi><mi>g<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>D<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">D(g\\circ f)(a)=Dg(f(a))Df(a)<\/annotation><\/semantics><\/math>.\nDenn der Zuwachs von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>h<\/mi><mo>+<\/mo><mi>o<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Ah+o(\\|h\\|)=O(\\|h\\|)<\/annotation><\/semantics><\/math>;\nEinsetzen in die lineare Näherung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>g<\/mi><annotation encoding=\"application/x-tex\">g<\/annotation><\/semantics><\/math>\nliefert den behaupteten linearen Term mit Rest\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>o<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">o(\\|h\\|)<\/annotation><\/semantics><\/math>.\nDie Reihenfolge der Matrizen ist wesentlich. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>u<\/mi><mo>+<\/mo><msup><mi>v<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">g(u,v)=u+v^2<\/annotation><\/semantics><\/math>\nerhält man am Ursprung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>g<\/mi><mo>∘<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">D(g\\circ f)=(1,0)<\/annotation><\/semantics><\/math>.<\/p>\n<p>Dagegen sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>x<\/mi><mi>y<\/mi><mi>/<\/mi><msqrt><mrow><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">q(x,y)=xy/\\sqrt{x^2+y^2}<\/annotation><\/semantics><\/math>\naußerhalb des Ursprungs und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q(0,0)=0<\/annotation><\/semantics><\/math>.\nAuf beiden Achsen ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q=0<\/annotation><\/semantics><\/math>,\nalso existieren dort die partiellen Ableitungen am Ursprung und sind\nnull. Die Funktion ist stetig, weil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>x<\/mi><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|xy|\\le (x^2+y^2)/2<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">h=(t,t)<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t\\ne0<\/annotation><\/semantics><\/math>\nist jedoch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|q(h)|/\\|h\\|=1/2<\/annotation><\/semantics><\/math>.\nDie notwendige lineare Abbildung wäre null, ihr Rest erfüllt die\nDefinition nicht. Auch Stetigkeit zusammen mit vorhandenen partiellen\nAbleitungen genügt daher nicht.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lokaler Umkehrsatz<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>:<\/mo><mi>U<\/mi><mo>⊂<\/mo><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mi>n<\/mi><\/msup><mo>→<\/mo><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mi>n<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f:U\\subset\\mathbb R^n\\to\\mathbb R^n<\/annotation><\/semantics><\/math>\nvon Klasse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>C<\/mi><mn>1<\/mn><\/msup><annotation encoding=\"application/x-tex\">C^1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>D<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\det Df(a)\\ne0<\/annotation><\/semantics><\/math>.\nDer Umkehrsatz garantiert offene Umgebungen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>V<\/mi><annotation encoding=\"application/x-tex\">V<\/annotation><\/semantics><\/math>\nvon\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a<\/mi><annotation encoding=\"application/x-tex\">a<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>W<\/mi><annotation encoding=\"application/x-tex\">W<\/annotation><\/semantics><\/math>\nvon\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(a)<\/annotation><\/semantics><\/math>,\nauf denen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>:<\/mo><mi>V<\/mi><mo>→<\/mo><mi>W<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f:V\\to W<\/annotation><\/semantics><\/math>\nbijektiv ist und eine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>C<\/mi><mn>1<\/mn><\/msup><annotation encoding=\"application/x-tex\">C^1<\/annotation><\/semantics><\/math>-Umkehrabbildung\nbesitzt. Aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>f<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>∘<\/mo><mi>f<\/mi><mo>=<\/mo><mi mathvariant=\"normal\">id<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f^{-1}\\circ f=\\operatorname{id}<\/annotation><\/semantics><\/math>\nund der Kettenregel folgt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>f<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>D<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">D(f^{-1})(f(a))=[Df(a)]^{-1}.<\/annotation><\/semantics><\/math><\/p>\n<p>Für das vorige Beispiel ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>D<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\det Df(0,0)=2<\/annotation><\/semantics><\/math>,\nalso existiert eine lokale Umkehrung mit Ableitung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}1&amp;0\\\\-1/2&amp;1/2\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt das lokale Koordinatengitter und seine Verformung. Die\nAussage ist lokal, nicht global:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>4<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(0,0)=(0,0)=f(-4,2)<\/annotation><\/semantics><\/math>,\nobwohl der Satz am Ursprung anwendbar ist. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mn>3<\/mn><\/msup><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(x,y)=(x^3,y)<\/annotation><\/semantics><\/math>\nist die Determinante am Ursprung null, die Funktion aber dennoch\nbijektiv; die Umkehrung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mroot><mi>u<\/mi><mn>3<\/mn><\/mroot><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(\\sqrt[3]{u},v)<\/annotation><\/semantics><\/math>\nist dort nicht differenzierbar. Eine singuläre Ableitung widerlegt somit\neine differenzierbare lokale Umkehrung, nicht jede Umkehrbarkeit.<\/p>\n<p>Der Existenzteil des Umkehrsatzes wird hier als Satz verwendet; sein\nvollständiger analytischer Beweis ist eine weiterführende Aufgabe. Die\nAbleitungsformel wurde oben aus der Kettenregel hergeleitet.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_047_DE.svg\"\nalt=\"Lokales Gitter und Bild unter f\" />\n<figcaption aria-hidden=\"true\">Lokales Gitter und Bild unter\nf<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Anwendung und Kontrolle<\/h2>\n<p>Für eine kleine Zieländerung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>u<\/mi><mo>,<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>02<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>06<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(\\Delta u,\\Delta v)=(0{,}02,0{,}06)<\/annotation><\/semantics><\/math>\num\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(0,0)<\/annotation><\/semantics><\/math>\nsagt die lineare Umkehrung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo>,<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>02<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>02<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(\\Delta x,\\Delta y)\\approx(0{,}02,0{,}02)<\/annotation><\/semantics><\/math>\nvoraus. Einsetzen ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0204<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>06<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0{,}0204,0{,}06)<\/annotation><\/semantics><\/math>;\nder Fehler der ersten Koordinate ist quadratisch. Die exakte lokale\nLösung folgt aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mi>v<\/mi><mo>−<\/mo><mn>2<\/mn><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x=v-2y<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><mn>2<\/mn><mi>y<\/mi><mo>+<\/mo><mi>v<\/mi><mo>−<\/mo><mi>u<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y^2-2y+v-u=0<\/annotation><\/semantics><\/math>:\nnahe null gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>1<\/mn><mo>−<\/mo><msqrt><mrow><mn>1<\/mn><mo>+<\/mo><mi>u<\/mi><mo>−<\/mo><mi>v<\/mi><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">y=1-\\sqrt{1+u-v}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mi>v<\/mi><mo>−<\/mo><mn>2<\/mn><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x=v-2y<\/annotation><\/semantics><\/math>.\nDer andere Zweig liegt nahe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=2<\/annotation><\/semantics><\/math>\nund gehört nicht zur betrachteten lokalen Umkehrung. Eine kleine\nDeterminante allein misst die numerische Kondition nicht zuverlässig;\ndazu sind unter anderem die Singulärwerte relevant. In <a\nhref=\"index.html?course=university_mathematics&amp;module=M11&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M11-L2<\/a> wird die Determinante zur\nFlächenskalierung eingesetzt.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne die Jacobi-Matrix von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mi>y<\/mi><mo>,<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(xy,x^2+y)<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,2)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bestimme für das Beispiel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\naus S3 die Determinante bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=1<\/annotation><\/semantics><\/math>\nund beurteile die Anwendbarkeit des Umkehrsatzes.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Berechne die normierte Restgröße von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>q<\/mi><annotation encoding=\"application/x-tex\">q<\/annotation><\/semantics><\/math>\nentlang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(t,t)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Bestimme die Ableitung der lokalen Umkehrung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>,<\/mo><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(2x+y,x+y)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Erkläre, warum lokale Umkehrbarkeit keine globale Injektivität\ngarantiert.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}2&amp;1\\\\2&amp;1\\end{pmatrix}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>−<\/mo><mn>2<\/mn><mi>y<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2-2y=0<\/annotation><\/semantics><\/math>;\nder Satz liefert dort keine lokale\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>C<\/mi><mn>1<\/mn><\/msup><annotation encoding=\"application/x-tex\">C^1<\/annotation><\/semantics><\/math>-Umkehrung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>\nfür jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t\\ne0<\/annotation><\/semantics><\/math>;\nder Grenzwert ist nicht null.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}1&amp;-1\\\\-1&amp;2\\end{pmatrix}<\/annotation><\/semantics><\/math>,\nüberall konstant.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Der Satz beschränkt die Abbildung auf geeignete Umgebungen. Das\nBeispiel aus S4 hat zwei verschiedene Urbilder von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,0)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.math.toronto.edu/courses/mat237y1/20189/notes/Chapter2/S2.2.html\">University\nof Toronto, MAT237, §2.2<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Theorem 1, differentiability and Jacobian\n· Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.math.toronto.edu/courses/mat237y1/20189/notes/Chapter3/S3.3.html\">University\nof Toronto, MAT237, §3.3<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Theorem 1, inverse function theorem ·\nZuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M11-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M11-L2 – Variablentransformation und Integralsätze<\/h1>\n<p><strong>Kursbereich:<\/strong> M11 – Analysis, lineare Algebra und Wahrscheinlichkeit vertieft<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Studiengrundlagen und\nVertiefung<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M11&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M11-L1<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor Analysis-Kern/Vertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du berechnest Flächenelemente nach Koordinatenwechsel, erkennst\nMehrfachüberdeckungen und unterscheidest nichtnegative Flächenskalierung\nvon orientierten Randintegralen. Du beweist den Satz von Green für\nRechtecke und berechnest Zirkulation und Fluss.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Variablentransformation<\/h2>\n<p>Aufbauend auf <a href=\"index.html?course=university_mathematics&amp;module=M11&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M11-L1<\/a> und <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4<\/a> sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>:<\/mo><mi>U<\/mi><mo>→<\/mo><mi>V<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T:U\\to V<\/annotation><\/semantics><\/math>\nein\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>C<\/mi><mn>1<\/mn><\/msup><annotation encoding=\"application/x-tex\">C^1<\/annotation><\/semantics><\/math>-Diffeomorphismus\noffener Teilmengen von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\mathbb R^2<\/annotation><\/semantics><\/math>,\nalso bijektiv mit stetig differenzierbarer Umkehrabbildung. Für\nintegrierbares\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>V<\/mi><annotation encoding=\"application/x-tex\">V<\/annotation><\/semantics><\/math>\ngilt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∫<\/mo><mi>V<\/mi><\/msub><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>y<\/mi><mo>=<\/mo><msub><mo>∫<\/mo><mi>U<\/mi><\/msub><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>D<\/mi><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>u<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>v<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_V f(x,y)\\,dx\\,dy=\\int_U f(T(u,v))\\,|\\det DT(u,v)|\\,du\\,dv.<\/annotation><\/semantics><\/math><\/p>\n<p>Das lokale Rechteck mit Seiten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>u<\/mi><mo>,<\/mo><mi>d<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">du,dv<\/annotation><\/semantics><\/math>\nwird in erster Ordnung durch die beiden Spalten von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mi>T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">DT<\/annotation><\/semantics><\/math>\naufgespannt. Die Fläche des Parallelogramms ist der Betrag ihrer\nDeterminante mal\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>u<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">du\\,dv<\/annotation><\/semantics><\/math>.\nDies motiviert die Formel; der allgemeine Integralsatz benötigt einen\neigenen Grenzübergangsbeweis. Beispielsweise liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>u<\/mi><mo>+<\/mo><mi>v<\/mi><mo>,<\/mo><mi>u<\/mi><mo>−<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">T(u,v)=(2u+v,u-v)<\/annotation><\/semantics><\/math>\ndie Determinante\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-3<\/annotation><\/semantics><\/math>.\nDas Einheitsquadrat hat als Bild ein Parallelogramm mit Fläche 3, nicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-3<\/annotation><\/semantics><\/math>.\nDie Orientierung wird umgekehrt, die Fläche bleibt nichtnegativ.\nRandstücke von Flächenmaß null können bei diesen Integralen weggelassen\nwerden.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Polarkoordinaten und Mehrfachüberdeckung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>r<\/mi><mo>,<\/mo><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>r<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo>,<\/mo><mi>r<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">T(r,\\theta)=(r\\cos\\theta,r\\sin\\theta)<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mi>T<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mi>r<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mi>r<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">DT=\\begin{pmatrix}\\cos\\theta&amp;-r\\sin\\theta\\\\\\sin\\theta&amp;r\\cos\\theta\\end{pmatrix}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>D<\/mi><mi>T<\/mi><mo>=<\/mo><mi>r<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\det DT=r<\/annotation><\/semantics><\/math>.\nAuf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>r<\/mi><mo>&lt;<\/mo><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0&lt;r&lt;R<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>θ<\/mi><mo>&lt;<\/mo><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0&lt;\\theta&lt;2\\pi<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nein Diffeomorphismus auf die offene Kreisscheibe ohne Ursprung und\npositiven radialen Schnitt. Die ausgelassenen Mengen haben Flächenmaß\nnull. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f(x,y)=x^2+y^2<\/annotation><\/semantics><\/math>\nfolgt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∫<\/mo><mrow><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><mo>&lt;<\/mo><msup><mi>R<\/mi><mn>2<\/mn><\/msup><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>A<\/mi><mo>=<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><\/msubsup><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>R<\/mi><\/msubsup><msup><mi>r<\/mi><mn>3<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>r<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>θ<\/mi><mo>=<\/mo><mfrac><mrow><mi>π<\/mi><msup><mi>R<\/mi><mn>4<\/mn><\/msup><\/mrow><mn>2<\/mn><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_{x^2+y^2&lt;R^2}(x^2+y^2)\\,dA=\\int_0^{2\\pi}\\int_0^R r^3\\,dr\\,d\\theta=\\frac{\\pi R^4}{2}.<\/annotation><\/semantics><\/math><\/p>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R=2<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>8<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">8\\pi<\/annotation><\/semantics><\/math>.\nWird das Winkelintervall auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,4\\pi)<\/annotation><\/semantics><\/math>\nerweitert, ist die Abbildung nicht injektiv und das naive Integral\nliefert den doppelten Wert. Die Singularität bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">r=0<\/annotation><\/semantics><\/math>\ndarf nicht als lokaler Diffeomorphismus behandelt werden; hier ist das\nEntfernen einer Nullmenge zulässig. Die Formel setzt außerdem voraus,\ndass das transformierte Integrand und die Grenzen zur selben Abbildung\ngehören.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Satz von Green: Zirkulation und Beweis am Rechteck<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>D<\/mi><annotation encoding=\"application/x-tex\">D<\/annotation><\/semantics><\/math>\neine beschränkte ebene Region mit stückweise glattem, einfachem\ngeschlossenem Rand, positiv (gegen den Uhrzeigersinn) orientiert, und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>,<\/mo><mi>Q<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P,Q<\/annotation><\/semantics><\/math>\nseien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>C<\/mi><mn>1<\/mn><\/msup><annotation encoding=\"application/x-tex\">C^1<\/annotation><\/semantics><\/math>\nauf einer offenen Umgebung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mover><mi>D<\/mi><mo accent=\"true\">¯<\/mo><\/mover><annotation encoding=\"application/x-tex\">\\overline D<\/annotation><\/semantics><\/math>.\nDann gilt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∮<\/mo><mrow><mi>∂<\/mi><mi>D<\/mi><\/mrow><\/msub><mi>P<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><mo>+<\/mo><mi>Q<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>y<\/mi><mo>=<\/mo><msub><mo>∬<\/mo><mi>D<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>∂<\/mi><mi>x<\/mi><\/msub><mi>Q<\/mi><mo>−<\/mo><msub><mi>∂<\/mi><mi>y<\/mi><\/msub><mi>P<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>A<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\oint_{\\partial D} P\\,dx+Q\\,dy=\\iint_D(\\partial_xQ-\\partial_yP)\\,dA.<\/annotation><\/semantics><\/math><\/p>\n<p>Für das Rechteck\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>×<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>c<\/mi><mo>,<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">D=[a,b]\\times[c,d]<\/annotation><\/semantics><\/math>\nträgt die untere Kante\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_a^b P(x,c)dx<\/annotation><\/semantics><\/math>\nbei, die rechte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mi>c<\/mi><mi>d<\/mi><\/msubsup><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_c^d Q(b,y)dy<\/annotation><\/semantics><\/math>,\ndie obere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">-\\int_a^b P(x,d)dx<\/annotation><\/semantics><\/math>\nund die linke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><msubsup><mo>∫<\/mo><mi>c<\/mi><mi>d<\/mi><\/msubsup><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">-\\int_c^d Q(a,y)dy<\/annotation><\/semantics><\/math>.\nDie Summe ist<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mi>c<\/mi><mi>d<\/mi><\/msubsup><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>d<\/mi><mi>y<\/mi><mo>−<\/mo><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>d<\/mi><mi>x<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_c^d[Q(b,y)-Q(a,y)]dy-\\int_a^b[P(x,d)-P(x,c)]dx.<\/annotation><\/semantics><\/math><\/p>\n<p>Der eindimensionale Hauptsatz ersetzt die Differenzen durch Integrale\nder jeweiligen partiellen Ableitung. Fubini erlaubt wegen Stetigkeit,\ndie Integrationsreihenfolge anzugleichen; damit entsteht exakt das\nFlächenintegral. Das beweist den Rechteckfall. Für allgemeinere Gebiete\nist eine zusätzliche Argumentation erforderlich, die hier nicht bewiesen\nwird. Bei einem Gebiet mit Löchern ist die positive Orientierung innen\nim Uhrzeigersinn, sodass das Gebiet stets links der Laufrichtung liegt.\nDort muss der Satz auf sämtliche Randkomponenten angewendet werden,\nsofern die Regularitätsannahmen erfüllt sind.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zirkulation, Fluss und Orientierung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mi>−<\/mi><msup><mi>y<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">P=-y^2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mn>2<\/mn><mi>x<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q=2xy<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>×<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">D=[0,2]\\times[0,1]<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q<\/mi><mi>x<\/mi><\/msub><mo>−<\/mo><msub><mi>P<\/mi><mi>y<\/mi><\/msub><mo>=<\/mo><mn>4<\/mn><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q_x-P_y=4y<\/annotation><\/semantics><\/math>;\ndie Zirkulation beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>0<\/mn><mn>2<\/mn><\/msubsup><msubsup><mo>∫<\/mo><mn>0<\/mn><mn>1<\/mn><\/msubsup><mn>4<\/mn><mi>y<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>y<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\int_0^2\\int_0^1 4y\\,dy\\,dx=4<\/annotation><\/semantics><\/math>.\nDirekte Randkontrolle: unten 0, rechts\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>0<\/mn><mn>1<\/mn><\/msubsup><mn>4<\/mn><mi>y<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\int_0^1 4y\\,dy=2<\/annotation><\/semantics><\/math>,\noben\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>2<\/mn><mn>0<\/mn><\/msubsup><mo>−<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\int_2^0 -1\\,dx=2<\/annotation><\/semantics><\/math>,\nlinks 0. Die Grafik zeigt die vier Beiträge. Bei umgekehrter\nRandorientierung beträgt die Zirkulation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-4<\/annotation><\/semantics><\/math>.<\/p>\n<p>Für ein Vektorfeld\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>P<\/mi><mo>,<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">F=(P,Q)<\/annotation><\/semantics><\/math>\nund den äußeren Einheitsnormalenvektor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\ngilt bei positivem Randumlauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>⋅<\/mo><mi>n<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>s<\/mi><mo>=<\/mo><mi>P<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>y<\/mi><mo>−<\/mo><mi>Q<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F\\cdot n\\,ds=P\\,dy-Q\\,dx<\/annotation><\/semantics><\/math>.\nAnwendung des Zirkulationssatzes auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>Q<\/mi><mo>,<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-Q,P)<\/annotation><\/semantics><\/math>\nergibt die Flussform\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∮<\/mo><mi>F<\/mi><mo>⋅<\/mo><mi>n<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>s<\/mi><mo>=<\/mo><msub><mo>∬<\/mo><mi>D<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>P<\/mi><mi>x<\/mi><\/msub><mo>+<\/mo><msub><mi>Q<\/mi><mi>y<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mi>A<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\oint F\\cdot n\\,ds=\\iint_D(P_x+Q_y)dA<\/annotation><\/semantics><\/math>.\nBeim selben Feld ist die Divergenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2x<\/annotation><\/semantics><\/math>\nund der äußere Fluss 4. Er ist eine geometrisch definierte Größe; wenn\nder Weg umgekehrt wird, muss die Formel für die äußere Normale angepasst\nwerden. Die beiden Sätze sind ebene Spezialfälle der Verbindung zwischen\nAbleitung und Randintegration; Stokes- und Gauß-Satz verallgemeinern sie\nauf geeignete dreidimensionale Gebiete und Flächen. Ein singuläres Feld,\netwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>y<\/mi><mo>,<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>y<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-y,x)/(x^2+y^2)<\/annotation><\/semantics><\/math>,\ndarf nicht ohne Prüfung der Definitionsmenge auf eine volle Kreisscheibe\nangewendet werden.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_048_DE.svg\"\nalt=\"Polargitter und positiv orientierter Rechteckrand\" />\n<figcaption aria-hidden=\"true\">Polargitter und positiv orientierter\nRechteckrand<\/figcaption>\n<\/figure>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne die Fläche des Bildes von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>×<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,2]\\times[0,3]<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>u<\/mi><mo>+<\/mo><mi>v<\/mi><mo>,<\/mo><mi>u<\/mi><mo>−<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">T(u,v)=(2u+v,u-v)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Integriere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>1<\/mn><annotation encoding=\"application/x-tex\">1<\/annotation><\/semantics><\/math>\nüber die Kreisscheibe mit Radius 3 in Polarkoordinaten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\theta\\in(0,4\\pi)<\/annotation><\/semantics><\/math>\nfür eine einfache Polarkoordinatentransformation ungeeignet?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Berechne die Zirkulation von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>y<\/mi><mo>,<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-y,x)<\/annotation><\/semantics><\/math>\num das positiv orientierte Rechteck\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>×<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,3]\\times[0,2]<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Bestimme den äußeren Fluss von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(x,y)<\/annotation><\/semantics><\/math>\ndurch denselben Rand.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mo>⋅<\/mo><mn>2<\/mn><mo>⋅<\/mo><mn>3<\/mn><mo>=<\/mo><mn>18<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3\\cdot2\\cdot3=18<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>0<\/mn><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><\/msubsup><msubsup><mo>∫<\/mo><mn>0<\/mn><mn>3<\/mn><\/msubsup><mi>r<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>r<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>θ<\/mi><mo>=<\/mo><mn>9<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_0^{2\\pi}\\int_0^3 r\\,dr\\,d\\theta=9\\pi<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Fast jeder Punkt der Scheibe wird zweimal überdeckt; Injektivität\nfehlt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q<\/mi><mi>x<\/mi><\/msub><mo>−<\/mo><msub><mi>P<\/mi><mi>y<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q_x-P_y=2<\/annotation><\/semantics><\/math>;\nZirkulation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>12<\/mn><annotation encoding=\"application/x-tex\">12<\/annotation><\/semantics><\/math>,\nim Uhrzeigersinn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>12<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-12<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>x<\/mi><\/msub><mo>+<\/mo><msub><mi>Q<\/mi><mi>y<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_x+Q_y=2<\/annotation><\/semantics><\/math>;\näußerer Fluss\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>12<\/mn><annotation encoding=\"application/x-tex\">12<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://ocw.mit.edu/ans7870/18/18.013a/textbook/chapter24/section02.html\">MIT\n18.013A, §24.2<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Area integrals and absolute Jacobian · Zuletzt\nabgerufen: 2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://math.libretexts.org/Courses/De_Anza_College/Calculus_IV:_Multivariable_Calculus/03:_Vector_Calculus/3.04:_Greens_Theorem\">De\nAnza College, Calculus IV, §3.4<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Circulation, rectangle proof, flux\nand regions with holes · Zuletzt abgerufen: 2026-11-24 · Inhaltlich\ngeprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M11-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M11-L3 – Skalarprodukte, Orthogonalprojektion und Spektralsatz<\/h1>\n<p><strong>Kursbereich:<\/strong> M11 – Analysis, lineare Algebra und Wahrscheinlichkeit vertieft<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Studiengrundlagen und\nVertiefung<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L5<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor Kern/Vertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du berechnest Orthogonalprojektionen und Gram–Schmidt-Basen, beweist\ndie Bestapproximation in endlichdimensionalen Unterräumen und\ndiagonalisierst reelle symmetrische Matrizen orthogonal.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Skalarprodukt und Bestapproximation<\/h2>\n<p>Auf einem reellen Vektorraum ist ein Skalarprodukt eine symmetrische\nbilineare Form mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo>,<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\langle x,x\\rangle&gt;0<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x\\ne0<\/annotation><\/semantics><\/math>.\nEs induziert die Norm\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo>=<\/mo><msqrt><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo>,<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\|x\\|=\\sqrt{\\langle x,x\\rangle}<\/annotation><\/semantics><\/math>.\nAus der Nichtnegativität von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>x<\/mi><mo>−<\/mo><mi>t<\/mi><mi>y<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\|x-ty\\|^2<\/annotation><\/semantics><\/math>\nfür alle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>∈<\/mo><mi mathvariant=\"double-struck\">ℝ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t\\in\\mathbb R<\/annotation><\/semantics><\/math>\nfolgt durch Minimieren bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>y<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">t=\\langle x,y\\rangle/\\|y\\|^2<\/annotation><\/semantics><\/math>\n(für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y\\ne0<\/annotation><\/semantics><\/math>)\ndie Cauchy–Schwarz-Ungleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\langle x,y\\rangle|\\le\\|x\\|\\|y\\|<\/annotation><\/semantics><\/math>.\nOrthogonalität bedeutet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\langle x,y\\rangle=0<\/annotation><\/semantics><\/math>.<\/p>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>W<\/mi><annotation encoding=\"application/x-tex\">W<\/annotation><\/semantics><\/math>\nein Unterraum mit endlicher Orthonormalbasis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><msub><mi>q<\/mi><mi>m<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">q_1,\\ldots,q_m<\/annotation><\/semantics><\/math>.\nSetze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mi>x<\/mi><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo>,<\/mo><msub><mi>q<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><msub><mi>q<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Px=\\sum_i\\langle x,q_i\\rangle q_i<\/annotation><\/semantics><\/math>.\nDann ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>−<\/mo><mi>P<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x-Px<\/annotation><\/semantics><\/math>\northogonal zu jedem Basisvektor und damit zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>W<\/mi><annotation encoding=\"application/x-tex\">W<\/annotation><\/semantics><\/math>.\nFür jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w<\/mi><mo>∈<\/mo><mi>W<\/mi><\/mrow><annotation encoding=\"application/x-tex\">w\\in W<\/annotation><\/semantics><\/math>\ngilt nach Pythagoras<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>x<\/mi><mo>−<\/mo><mi>w<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>x<\/mi><mo>−<\/mo><mi>P<\/mi><mi>x<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mn>2<\/mn><\/msup><mi>+<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>P<\/mi><mi>x<\/mi><mo>−<\/mo><mi>w<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\|x-w\\|^2=\\|x-Px\\|^2+\\|Px-w\\|^2.<\/annotation><\/semantics><\/math><\/p>\n<p>Die rechte Seite ist genau bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w<\/mi><mo>=<\/mo><mi>P<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">w=Px<\/annotation><\/semantics><\/math>\nminimal. In euklidischen Koordinaten mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>q<\/mi><mn>1<\/mn><\/msub><mspace width=\"0.222em\"><\/mspace><mi>⋯<\/mi><mspace width=\"0.222em\"><\/mspace><msub><mi>q<\/mi><mi>m<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Q=(q_1\\ \\cdots\\ q_m)<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mi>Q<\/mi><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">P=QQ^T<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>P<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mi>P<\/mi><mo>=<\/mo><msup><mi>P<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">P^2=P=P^T<\/annotation><\/semantics><\/math>.\nFür eine nichtorthogonale Basis mit vollrangiger Spaltenmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\nlautet die Projektionsmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>B<\/mi><mi>T<\/mi><\/msup><mi>B<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><msup><mi>B<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">B(B^TB)^{-1}B^T<\/annotation><\/semantics><\/math>:\nDie Normalgleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>B<\/mi><mi>T<\/mi><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mi>B<\/mi><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">B^T(x-Bc)=0<\/annotation><\/semantics><\/math>\nliefert die Koeffizienten. Ohne vollen Spaltenrang ist diese\nInversenformel nicht gültig.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gram–Schmidt und QR-Zerlegung<\/h2>\n<p>Aus unabhängigen Vektoren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><msub><mi>a<\/mi><mi>m<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">a_1,\\ldots,a_m<\/annotation><\/semantics><\/math>\nkonstruiert man rekursiv\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mi>j<\/mi><\/msub><mo>=<\/mo><msub><mi>a<\/mi><mi>j<\/mi><\/msub><mo>−<\/mo><msub><mo>∑<\/mo><mrow><mi>i<\/mi><mo>&lt;<\/mo><mi>j<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msub><mi>a<\/mi><mi>j<\/mi><\/msub><mo>,<\/mo><msub><mi>q<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><msub><mi>q<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">v_j=a_j-\\sum_{i&lt;j}\\langle a_j,q_i\\rangle q_i<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mi>j<\/mi><\/msub><mo>=<\/mo><msub><mi>v<\/mi><mi>j<\/mi><\/msub><mi>/<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><msub><mi>v<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><annotation encoding=\"application/x-tex\">q_j=v_j/\\|v_j\\|<\/annotation><\/semantics><\/math>.\nDas Skalarprodukt von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>v<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">v_j<\/annotation><\/semantics><\/math>\nmit jedem früheren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>q<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">q_i<\/annotation><\/semantics><\/math>\nist null. Weil die bisherigen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>q<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">q_i<\/annotation><\/semantics><\/math>\ndenselben Raum wie die bisherigen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>a<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">a_i<\/annotation><\/semantics><\/math>\naufspannen, ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mi>j<\/mi><\/msub><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v_j\\ne0<\/annotation><\/semantics><\/math>\naufgrund linearer Unabhängigkeit. Induktiv bleiben die aufgespannten\nTeilräume gleich. In euklidischen Koordinaten ergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mi>Q<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B=QR<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mo>=<\/mo><msubsup><mi>q<\/mi><mi>i<\/mi><mi>T<\/mi><\/msubsup><msub><mi>a<\/mi><mi>j<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">R_{ij}=q_i^Ta_j<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i<\/mi><mo>≤<\/mo><mi>j<\/mi><\/mrow><annotation encoding=\"application/x-tex\">i\\le j<\/annotation><\/semantics><\/math>,\nsonst null. Die Diagonale ist positiv. Bei nahezu abhängigen Vektoren\nkönnen Rundungsfehler die Orthogonalität beeinträchtigen; numerisch\nwerden häufig Householder-Transformationen oder modifiziertes\nGram–Schmidt eingesetzt.<\/p>\n<p>Beispiel:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">a_1=(1,1,0)^T<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">a_2=(1,0,1)^T<\/annotation><\/semantics><\/math>.\nDann\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">q_1=(1,1,0)^T/\\sqrt2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><mi>/<\/mi><msqrt><mn>6<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">q_2=(1,-1,2)^T/\\sqrt6<\/annotation><\/semantics><\/math>.\nDie Projektion von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(2,0,0)^T<\/annotation><\/semantics><\/math>\nauf ihren Spann ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(4/3,2/3,2/3)^T<\/annotation><\/semantics><\/math>.\nDer Rest\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mi>−<\/mi><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><mo>,<\/mo><mi>−<\/mi><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(2/3,-2/3,-2/3)^T<\/annotation><\/semantics><\/math>\nist zu beiden Ausgangsvektoren orthogonal. In der Grafik wird der\nzweidimensionale Spezialfall\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">x=(3,1)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">span<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">W=\\operatorname{span}(1,1)<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mi>x<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Px=(2,2)<\/annotation><\/semantics><\/math>\ngezeigt.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_049_DE.svg\"\nalt=\"Orthogonalprojektion und Eigenrichtungen\" />\n<figcaption aria-hidden=\"true\">Orthogonalprojektion und\nEigenrichtungen<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Spektralsatz und Beweis<\/h2>\n<p>Für jede reelle symmetrische Matrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><msup><mi>A<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">A=A^T<\/annotation><\/semantics><\/math>\nexistiert eine orthonormale Eigenbasis, also\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mi>Q<\/mi><mi mathvariant=\"normal\">Λ<\/mi><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">A=Q\\Lambda Q^T<\/annotation><\/semantics><\/math>\nmit orthogonalem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>\nund reeller Diagonalmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Λ<\/mi><annotation encoding=\"application/x-tex\">\\Lambda<\/annotation><\/semantics><\/math>.\nEin Beweis verwendet das Maximum von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mi>T<\/mi><\/msup><mi>A<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x^TAx<\/annotation><\/semantics><\/math>\nauf der kompakten Einheitssphäre. Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>u<\/mi><annotation encoding=\"application/x-tex\">u<\/annotation><\/semantics><\/math>\nein Maximierer. Für jeden Einheitsvektor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>⟂<\/mo><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v\\perp u<\/annotation><\/semantics><\/math>\nmuss die Ableitung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>t<\/mi><mo>+<\/mo><mi>v<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>t<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><mi>A<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>t<\/mi><mo>+<\/mo><mi>v<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(u\\cos t+v\\sin t)^TA(u\\cos t+v\\sin t)<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>\nnull sein. Sie ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><msup><mi>v<\/mi><mi>T<\/mi><\/msup><mi>A<\/mi><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2v^TAu<\/annotation><\/semantics><\/math>.\nAlso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>u<\/mi><mo>=<\/mo><mi>λ<\/mi><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Au=\\lambda u<\/annotation><\/semantics><\/math>.\nWegen Symmetrie ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>u<\/mi><mo>⟂<\/mo><\/msup><annotation encoding=\"application/x-tex\">u^\\perp<\/annotation><\/semantics><\/math>\ninvariant:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>u<\/mi><mi>T<\/mi><\/msup><mi>A<\/mi><mi>w<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>A<\/mi><mi>u<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><mi>w<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u^TAw=(Au)^Tw=0<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w<\/mi><mo>⟂<\/mo><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">w\\perp u<\/annotation><\/semantics><\/math>.\nDie Einschränkung ist erneut symmetrisch. Induktion über die Dimension,\nmit Dimension eins als Basisfall, liefert die Eigenbasis.<\/p>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>4<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>2<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>4<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">A=\\begin{pmatrix}4&amp;2\\\\2&amp;4\\end{pmatrix}<\/annotation><\/semantics><\/math>\nsind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mo>+<\/mo><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">q_+=(1,1)^T/\\sqrt2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mo>−<\/mo><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">q_-=(1,-1)^T/\\sqrt2<\/annotation><\/semantics><\/math>\nEigenvektoren mit Eigenwerten 6 und 2. Damit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>6<\/mn><msub><mi>q<\/mi><mo>+<\/mo><\/msub><msubsup><mi>q<\/mi><mo>+<\/mo><mi>T<\/mi><\/msubsup><mo>+<\/mo><mn>2<\/mn><msub><mi>q<\/mi><mo>−<\/mo><\/msub><msubsup><mi>q<\/mi><mo>−<\/mo><mi>T<\/mi><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">A=6q_+q_+^T+2q_-q_-^T<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>A<\/mi><mi>k<\/mi><\/msup><mo>=<\/mo><msup><mn>6<\/mn><mi>k<\/mi><\/msup><msub><mi>q<\/mi><mo>+<\/mo><\/msub><msubsup><mi>q<\/mi><mo>+<\/mo><mi>T<\/mi><\/msubsup><mo>+<\/mo><msup><mn>2<\/mn><mi>k<\/mi><\/msup><msub><mi>q<\/mi><mo>−<\/mo><\/msub><msubsup><mi>q<\/mi><mo>−<\/mo><mi>T<\/mi><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">A^k=6^k q_+q_+^T+2^k q_-q_-^T<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k\\ge0<\/annotation><\/semantics><\/math>.\nDie Matrix ist positiv definit, weil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mi>T<\/mi><\/msup><mi>A<\/mi><mi>x<\/mi><mo>=<\/mo><mn>6<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>q<\/mi><mo>+<\/mo><mi>T<\/mi><\/msubsup><mi>x<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>q<\/mi><mo>−<\/mo><mi>T<\/mi><\/msubsup><mi>x<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x^TAx=6(q_+^Tx)^2+2(q_-^Tx)^2&gt;0<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x\\ne0<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Grenzen und Anwendungen<\/h2>\n<p>Bei der linearen Ausgleichsrechnung minimiert eine QR-Zerlegung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>B<\/mi><mi>c<\/mi><mo>−<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\|Bc-y\\|<\/annotation><\/semantics><\/math>:\nWeil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><mi>Q<\/mi><mo>=<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q^TQ=I<\/annotation><\/semantics><\/math>,\nlautet die eindeutige Lösung bei vollem Rang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mi>c<\/mi><mo>=<\/mo><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Rc=Q^Ty<\/annotation><\/semantics><\/math>.\nDies vermeidet die explizite Bildung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>B<\/mi><mi>T<\/mi><\/msup><mi>B<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B^TB<\/annotation><\/semantics><\/math>,\nderen 2-Norm-Konditionszahl bei vollem Rang das Quadrat der von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\nist. Eine idempotente Matrix ist nicht notwendig eine\nOrthogonalprojektion:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}1&amp;1\\\\0&amp;0\\end{pmatrix}<\/annotation><\/semantics><\/math>\nprojiziert schief auf die erste Achse. Sie ist auch nicht symmetrisch.\nEine reelle Matrix kann selbst bei reellen Eigenwerten nicht\ndiagonalisierbar sein, etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}1&amp;1\\\\0&amp;1\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nDer Spektralsatz hier ist endlichdimensional; unendlichdimensionale\nOperatoren erfordern weitere Voraussetzungen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Projiziere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(4,2)<\/annotation><\/semantics><\/math>\nauf die Gerade mit Richtungsvektor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,2)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Orthogonalisiere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,0,1)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,1,0)<\/annotation><\/semantics><\/math>\n(ohne Normierung).<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Bestimme die Eigenwerte von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>3<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\begin{pmatrix}3&amp;1\\\\1&amp;3\\end{pmatrix}<\/annotation><\/semantics><\/math>\nund eine orthonormale Eigenbasis.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Warum ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mi>Q<\/mi><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">P=QQ^T<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><mi>Q<\/mi><mo>=<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q^TQ=I<\/annotation><\/semantics><\/math>\nidempotent?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Prüfe die schiefe Projektion aus S5 auf Symmetrie und gib ihren Kern\nan.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>8<\/mn><mi>/<\/mi><mn>5<\/mn><mo>,<\/mo><mn>16<\/mn><mi>/<\/mi><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(8/5,16/5)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,0,1)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1/2,1,-1/2)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">4,2<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">(1,1)/\\sqrt2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">(1,-1)/\\sqrt2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>P<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><mi>Q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>Q<\/mi><mi>T<\/mi><\/msup><mo>=<\/mo><mi>P<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P^2=Q(Q^TQ)Q^T=P<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Nicht symmetrisch; Kern\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">span<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{span}(1,-1)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://tudelft.roelofkoekoek.nl/teaching/linalg/orthogonality/gram-schmidt.html\">TU\nDelft, R. Koekoek, The Gram-Schmidt process<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Projection formula,\nGram–Schmidt, QR · Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft:\n2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://tudelft.roelofkoekoek.nl/teaching/linalg/symmetric/spectral_theorem.html\">TU\nDelft, R. Koekoek, The spectral theorem<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Orthogonal diagonalization\nand spectral decomposition · Zuletzt abgerufen: 2026-11-24 · Inhaltlich\ngeprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M11-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M11-L4 – Gesetz der großen Zahlen und zentraler Grenzwertsatz<\/h1>\n<p><strong>Kursbereich:<\/strong> M11 – Analysis, lineare Algebra und Wahrscheinlichkeit vertieft<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Studiengrundlagen und\nVertiefung<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L7<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L2<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor Kern/Vertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du unterscheidest stochastische Konvergenzarten, beweist das schwache\nGesetz der großen Zahlen mit Tschebyscheff und wendest den zentralen\nGrenzwertsatz auf standardisierte Summen an.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Stichprobenmittel und schwaches Gesetz<\/h2>\n<p>Seien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">X_i<\/annotation><\/semantics><\/math>\nunabhängig und identisch verteilt (i.i.d.) mit Erwartungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>μ<\/mi><annotation encoding=\"application/x-tex\">\\mu<\/annotation><\/semantics><\/math>\nund endlicher Varianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\sigma^2<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>X<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msub><mo>=<\/mo><msup><mi>n<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><msubsup><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/msubsup><msub><mi>X<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\bar X_n=n^{-1}\\sum_{i=1}^nX_i<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><msub><mover><mi>X<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msub><mo>=<\/mo><mi>μ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E\\bar X_n=\\mu<\/annotation><\/semantics><\/math>\nund aufgrund der verschwindenden Kovarianzen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mover><mi>X<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(\\bar X_n)=\\sigma^2/n<\/annotation><\/semantics><\/math>.\nDie Tschebyscheff-Ungleichung folgt aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>Y<\/mi><mo>−<\/mo><mi>E<\/mi><mi>Y<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>≥<\/mo><msup><mi>ε<\/mi><mn>2<\/mn><\/msup><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>Y<\/mi><mo>−<\/mo><mi>E<\/mi><mi>Y<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≥<\/mo><mi>ε<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E(Y- EY)^2\\ge\\varepsilon^2P(|Y-EY|\\ge\\varepsilon)<\/annotation><\/semantics><\/math>.\nSomit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mover><mi>X<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msub><mo>−<\/mo><mi>μ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≥<\/mo><mi>ε<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mfrac><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mrow><mi>n<\/mi><msup><mi>ε<\/mi><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le\\frac{\\sigma^2}{n\\varepsilon^2}\\to0<\/annotation><\/semantics><\/math><\/p>\n<p>für jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ε<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon&gt;0<\/annotation><\/semantics><\/math>.\nDies ist Konvergenz in Wahrscheinlichkeit und beweist das schwache\nGesetz unter den genannten Annahmen. Der mittlere quadratische Fehler\ngeht ebenfalls gegen null. Die Abschätzung ist häufig konservativ. Für\nBernoulli-Beobachtungen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}3<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>1000<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=1000<\/annotation><\/semantics><\/math>\nbeträgt die obere Schranke bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ε<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>05<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon=0{,}05<\/annotation><\/semantics><\/math>\nbeispielsweise\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>084<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}084<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Konvergenzarten und Abhängigkeit<\/h2>\n<p>Fast sichere Konvergenz bedeutet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>ω<\/mi><mo>:<\/mo><msub><mi>X<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>→<\/mo><mi>X<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(\\{\\omega:X_n(\\omega)\\to X(\\omega)\\})=1<\/annotation><\/semantics><\/math>.\nDas starke Gesetz liefert für i.i.d. Zufallsvariablen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E|X_1|&lt;\\infty<\/annotation><\/semantics><\/math>\ndie fast sichere Konvergenz des Mittels. Es ist hier als Satz angegeben,\nohne vollständigen Beweis. Fast sichere Konvergenz impliziert Konvergenz\nin Wahrscheinlichkeit, diese wiederum Verteilungskonvergenz. Bei\nVerteilungskonvergenz konvergieren die Verteilungsfunktionen an\nStetigkeitsstellen der Grenzverteilungsfunktion. Die Umkehrungen gelten\nim Allgemeinen nicht. Beispielsweise konvergieren unabhängige\nIndikatoren mit Erfolgswahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/n<\/annotation><\/semantics><\/math>\nin Wahrscheinlichkeit gegen null, aber wegen des zweiten\nBorel–Cantelli-Lemmas treten Erfolge fast sicher unendlich oft auf.<\/p>\n<p>Unabhängigkeit lässt sich nicht einfach weglassen: Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X_i=Y<\/annotation><\/semantics><\/math>\nfür alle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>i<\/mi><annotation encoding=\"application/x-tex\">i<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>∼<\/mo><mrow><mi mathvariant=\"normal\">B<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">i<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Y\\sim\\mathrm{Bernoulli}(1/2)<\/annotation><\/semantics><\/math>.\nDann bleibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>X<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msub><mo>=<\/mo><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\bar X_n=Y<\/annotation><\/semantics><\/math>;\ndie Varianz sinkt nicht. Eine wachsende Stichprobe aus vollständig\nredundanten Beobachtungen ist keine zusätzliche Information.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zentraler Grenzwertsatz<\/h2>\n<p>Für i.i.d.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">X_i<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mo>&lt;<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0&lt;\\sigma^2&lt;\\infty<\/annotation><\/semantics><\/math>\nlautet die standardisierte Summe<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mfrac><mrow><munder><mo>∑<\/mo><mi>i<\/mi><\/munder><msub><mi>X<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><mi>n<\/mi><mi>μ<\/mi><\/mrow><mrow><mi>σ<\/mi><msqrt><mi>n<\/mi><\/msqrt><\/mrow><\/mfrac><mo>=<\/mo><mfrac><mrow><msqrt><mi>n<\/mi><\/msqrt><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mover><mi>X<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msub><mo>−<\/mo><mi>μ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><mi>σ<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_n=\\frac{\\sum_iX_i-n\\mu}{\\sigma\\sqrt n}=\\frac{\\sqrt n(\\bar X_n-\\mu)}{\\sigma}.<\/annotation><\/semantics><\/math><\/p>\n<p>Der zentrale Grenzwertsatz besagt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>n<\/mi><\/msub><mo>⇒<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Z_n\\Rightarrow N(0,1)<\/annotation><\/semantics><\/math>.\nIm Gegensatz zum Gesetz der großen Zahlen beschreibt er die Form der\nskalierten Schwankungen. Eine Beweisskizze: Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><mi>μ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>σ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Y=(X_1-\\mu)/\\sigma<\/annotation><\/semantics><\/math>\ngilt für die charakteristische Funktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>φ<\/mi><mi>Y<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mi>t<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo>+<\/mo><mi>o<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>t<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\varphi_Y(t)=1-t^2/2+o(t^2)<\/annotation><\/semantics><\/math>\nbei null (Taylorentwicklung und dominierte Konvergenz bei endlichem\nzweiten Moment). Unabhängigkeit liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>φ<\/mi><msub><mi>Z<\/mi><mi>n<\/mi><\/msub><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>φ<\/mi><mi>Y<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mi>/<\/mi><msqrt><mi>n<\/mi><\/msqrt><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>n<\/mi><\/msup><mo>→<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><msup><mi>t<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\varphi_{Z_n}(t)=\\varphi_Y(t/\\sqrt n)^n\\to e^{-t^2/2}<\/annotation><\/semantics><\/math>.\nDer Stetigkeitssatz von Lévy ergibt die behauptete\nVerteilungskonvergenz; dieser wird als weiterführender Satz\nvorausgesetzt.<\/p>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>∼<\/mo><mrow><mi mathvariant=\"normal\">B<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>100<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S\\sim\\mathrm{Bin}(100,0{,}3)<\/annotation><\/semantics><\/math>\nsind Erwartungswert 30 und Varianz 21. Mit Stetigkeitskorrektur ergibt\nsich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>25<\/mn><mo>≤<\/mo><mi>S<\/mi><mo>≤<\/mo><mn>35<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mi mathvariant=\"normal\">Φ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>5<\/mn><mo>,<\/mo><mn>5<\/mn><mi>/<\/mi><msqrt><mn>21<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi mathvariant=\"normal\">Φ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>5<\/mn><mo>,<\/mo><mn>5<\/mn><mi>/<\/mi><msqrt><mn>21<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>770<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(25\\le S\\le35)\\approx\\Phi(5{,}5/\\sqrt{21})-\\Phi(-5{,}5/\\sqrt{21})\\approx0{,}770<\/annotation><\/semantics><\/math>.\nDie Korrektur berücksichtigt die Gitterstruktur. Bei kleinen erwarteten\nErfolgs- oder Misserfolgszahlen kann die Normalapproximation schlecht\nsein; der Satz nennt keine universelle Mindeststichprobengröße.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Reproduzierbares Experiment<\/h2>\n<p>Der folgende Code simuliert für jede Stichprobengröße 20.000\nunabhängige Bernoulli-Summen über die exakte Binomialverteilung. Er\nvergleicht den empirischen mittleren quadratischen Fehler des Mittels\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p(1-p)/n<\/annotation><\/semantics><\/math>\nund bestimmt den Anteil standardisierter Summen im Intervall\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-1,1]<\/annotation><\/semantics><\/math>.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">import<\/span> numpy <span class=\"im\">as<\/span> np<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>rng <span class=\"op\">=<\/span> np.random.default_rng(<span class=\"dv\">165<\/span>)<\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>p <span class=\"op\">=<\/span> <span class=\"fl\">0.3<\/span><\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">for<\/span> n <span class=\"kw\">in<\/span> (<span class=\"dv\">20<\/span>, <span class=\"dv\">100<\/span>, <span class=\"dv\">1000<\/span>):<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    s <span class=\"op\">=<\/span> rng.binomial(n, p, size<span class=\"op\">=<\/span><span class=\"dv\">20000<\/span>)<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    z <span class=\"op\">=<\/span> (s<span class=\"op\">-<\/span>n<span class=\"op\">*<\/span>p)<span class=\"op\">/<\/span>np.sqrt(n<span class=\"op\">*<\/span>p<span class=\"op\">*<\/span>(<span class=\"dv\">1<\/span><span class=\"op\">-<\/span>p))<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"bu\">print<\/span>(n, np.mean((s<span class=\"op\">/<\/span>n<span class=\"op\">-<\/span>p)<span class=\"op\">**<\/span><span class=\"dv\">2<\/span>), p<span class=\"op\">*<\/span>(<span class=\"dv\">1<\/span><span class=\"op\">-<\/span>p)<span class=\"op\">/<\/span>n,<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>          np.mean(np.<span class=\"bu\">abs<\/span>(z) <span class=\"op\">&lt;=<\/span> <span class=\"dv\">1<\/span>))<\/span><\/code><\/pre><\/div>\n<p>Die Grenzwahrscheinlichkeit für das letzte Intervall ist etwa 0,6827.\nDas Experiment ist eine Plausibilitätskontrolle, kein Beweis. Der\nZufallsfehler des empirischen Anteils beträgt in der Größenordnung\nhöchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><msqrt><mn>20000<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">1/(2\\sqrt{20000})<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt die schrumpfende Standardabweichung des Mittels und die\nexakte Binomialmasse in standardisierten Koordinaten, dividiert durch\ndie Gitterbreite (Dichtevergleich).<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_050_DE.svg\"\nalt=\"Standardabweichung des Mittels und standardisierte Binomialverteilungen\" />\n<figcaption aria-hidden=\"true\">Standardabweichung des Mittels und\nstandardisierte Binomialverteilungen<\/figcaption>\n<\/figure>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne die Varianz des Mittels aus 400 i.i.d. Beobachtungen mit\nVarianz 9.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß muss\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nmindestens sein, damit die Tschebyscheff-Schranke bei\nBernoulli-<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=1/2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ε<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon=0{,}1<\/annotation><\/semantics><\/math>\nhöchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>05<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}05<\/annotation><\/semantics><\/math>\nist?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Standardisiere eine Binomialsumme mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>200<\/mn><mo>,<\/mo><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=200,p=0{,}25<\/annotation><\/semantics><\/math>\nbei beobachtetem Wert 60.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Warum versagt der Standardbeweis des Grenzwertsatzes bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma^2=0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Erkläre den Unterschied zwischen schwachem Gesetz und zentralem\nGrenzwertsatz.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>9<\/mn><mi>/<\/mi><mn>400<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0225<\/mn><\/mrow><annotation encoding=\"application/x-tex\">9/400=0{,}0225<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>≥<\/mo><mn>500<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n\\ge500<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>60<\/mn><mo>−<\/mo><mn>50<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mrow><mn>37<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><\/msqrt><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>633<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(60-50)/\\sqrt{37{,}5}\\approx1{,}633<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Die Standardisierung dividiert durch null; die Beobachtungen sind\nfast sicher konstant.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Das erste zeigt Konzentration des Mittels um\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>μ<\/mi><annotation encoding=\"application/x-tex\">\\mu<\/annotation><\/semantics><\/math>,\ndas zweite beschreibt die Grenzverteilung seiner auf der Skala\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msqrt><mi>n<\/mi><\/msqrt><annotation encoding=\"application/x-tex\">\\sqrt n<\/annotation><\/semantics><\/math>\nvergrößerten Abweichung.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.probabilitycourse.com/chapter7/7_1_1_law_of_large_numbers.php\">H.\nPishro-Nik, Introduction to Probability, §7.1.1<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Weak law,\nChebyshev · Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft:\n2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.probabilitycourse.com/chapter7/7_1_2_central_limit_theorem.php\">H.\nPishro-Nik, Introduction to Probability, §7.1.2<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · i.i.d. CLT,\nstandardization, normal approximation · Zuletzt abgerufen: 2026-11-24 ·\nInhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M11-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M11-L5 – Banachräume und Fixpunktsatz<\/h1>\n<p><strong>Kursbereich:<\/strong> M11 – Analysis, lineare Algebra und Wahrscheinlichkeit vertieft<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Vertiefung und Master-Brücke<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M2&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M2-L4<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M2&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">M2-L7<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L9&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L9<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor Vertiefung / Master-Brücke<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du unterscheidest normierte und vollständige Räume, beweist den\nBanachschen Fixpunktsatz, berechnest Fehlergrenzen und setzt das\nVerfahren für eine Integralgleichung ein.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Vollständigkeit und Banachräume<\/h2>\n<p>Eine Norm auf einem reellen oder komplexen Vektorraum\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>\nerfüllt Definitheit, absolute Homogenität und Dreiecksungleichung. Sie\ninduziert die Metrik\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d(x,y)=\\|x-y\\|<\/annotation><\/semantics><\/math>.\nEine Folge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(x_n)<\/annotation><\/semantics><\/math>\nheißt Cauchyfolge, falls für jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ε<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon&gt;0<\/annotation><\/semantics><\/math>\nein\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nexistiert, sodass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><msub><mi>x<\/mi><mi>m<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mo>&lt;<\/mo><mi>ε<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\|x_n-x_m\\|&lt;\\varepsilon<\/annotation><\/semantics><\/math>\nfür alle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>,<\/mo><mi>m<\/mi><mo>≥<\/mo><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n,m\\ge N<\/annotation><\/semantics><\/math>.\nEin normierter Raum heißt Banachraum, wenn jede Cauchyfolge in ihm\nkonvergiert. Vollständigkeit betrifft also nicht nur die Abstände,\nsondern auch die Existenz des Grenzwerts im Raum.<\/p>\n<p>Der Raum\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">C([0,1])<\/annotation><\/semantics><\/math>\nder stetigen reellen Funktionen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>f<\/mi><msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>∞<\/mi><\/msub><mo>=<\/mo><msub><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mrow><mi>t<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\|f\\|_\\infty=\\max_{t\\in[0,1]}|f(t)|<\/annotation><\/semantics><\/math>\nist vollständig: Eine Cauchyfolge in dieser Norm ist punktweise Cauchy\nund besitzt wegen Vollständigkeit von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"double-struck\">ℝ<\/mi><annotation encoding=\"application/x-tex\">\\mathbb R<\/annotation><\/semantics><\/math>\neinen punktweisen Grenzwert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>.\nAus der einheitlichen Cauchyabschätzung folgt durch Grenzübergang in\neinem Index\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><mi>f<\/mi><msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>∞<\/mi><\/msub><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\|f_n-f\\|_\\infty\\to0<\/annotation><\/semantics><\/math>.\nDer gleichmäßige Grenzwert stetiger Funktionen ist stetig\n(Dreiecksungleichung mit einem festen hinreichend späten Folgenglied).\nDagegen ist der Unterraum der Polynome mit dieser Norm unvollständig:\nDie Taylorpolynome von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mi>t<\/mi><\/msup><annotation encoding=\"application/x-tex\">e^t<\/annotation><\/semantics><\/math>\nkonvergieren auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>\ngleichmäßig zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mi>t<\/mi><\/msup><annotation encoding=\"application/x-tex\">e^t<\/annotation><\/semantics><\/math>,\ndas kein Polynom ist. Eine abgeschlossene Teilmenge eines vollständigen\nmetrischen Raumes ist vollständig, auch wenn sie kein Vektorraum\nist.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Fixpunktsatz und Fehlergrenzen<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>X<\/mi><mo>,<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(X,d)<\/annotation><\/semantics><\/math>\nnichtleer und vollständig und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>:<\/mo><mi>X<\/mi><mo>→<\/mo><mi>X<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T:X\\to X<\/annotation><\/semantics><\/math>\neine Kontraktion: Es gibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">q\\in[0,1)<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mi>x<\/mi><mo>,<\/mo><mi>T<\/mi><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mi>q<\/mi><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d(Tx,Ty)\\le qd(x,y)<\/annotation><\/semantics><\/math>\nfür alle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo>∈<\/mo><mi>X<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x,y\\in X<\/annotation><\/semantics><\/math>.\nDann existiert genau ein Fixpunkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo>=<\/mo><mi>T<\/mi><msup><mi>x<\/mi><mo>*<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">x^*=Tx^*<\/annotation><\/semantics><\/math>.\nFür jeden Start\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>∈<\/mo><mi>X<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x_0\\in X<\/annotation><\/semantics><\/math>\nkonvergiert die Iteration\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>T<\/mi><msub><mi>x<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">x_{n+1}=Tx_n<\/annotation><\/semantics><\/math>\nzu ihm.<\/p>\n<p>Beweis: Wiederholtes Anwenden der Kontraktionsabschätzung gibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><msup><mi>q<\/mi><mi>n<\/mi><\/msup><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d(x_{n+1},x_n)\\le q^n d(x_1,x_0)<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>&gt;<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m&gt;n<\/annotation><\/semantics><\/math>\nergibt die Dreiecksungleichung<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>m<\/mi><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><munderover><mo>∑<\/mo><mrow><mi>k<\/mi><mo>=<\/mo><mi>n<\/mi><\/mrow><mrow><mi>m<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/munderover><msup><mi>q<\/mi><mi>k<\/mi><\/msup><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mfrac><msup><mi>q<\/mi><mi>n<\/mi><\/msup><mrow><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><\/mrow><\/mfrac><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">d(x_m,x_n)\\le\\sum_{k=n}^{m-1}q^k d(x_1,x_0)\\le\\frac{q^n}{1-q}d(x_1,x_0).<\/annotation><\/semantics><\/math><\/p>\n<p>Damit ist die Folge Cauchy und hat einen Grenzwert in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>.\nDie Lipschitz-Stetigkeit von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nerlaubt den Grenzübergang in der Iteration; folglich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo>=<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Tx^*=x^*<\/annotation><\/semantics><\/math>.\nFür zwei Fixpunkte wäre\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo>,<\/mo><msup><mi>y<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mi>q<\/mi><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo>,<\/mo><msup><mi>y<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d(x^*,y^*)\\le qd(x^*,y^*)<\/annotation><\/semantics><\/math>,\nalso müssen sie gleich sein. Grenzübergang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>→<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\to\\infty<\/annotation><\/semantics><\/math>\nliefert die a-priori-Abschätzung rechts oben. Dieselbe Rechnung mit\nStart\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">x_n<\/annotation><\/semantics><\/math>\nliefert die a-posteriori-Schranke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo>,<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d(x_n,x^*)\\le d(x_{n+1},x_n)/(1-q)<\/annotation><\/semantics><\/math>;\nmit dem vorherigen Schritt ist sie höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mrow><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">q d(x_n,x_{n-1})/(1-q)<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>≥<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n\\ge1<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Gegenbeispiele<\/h2>\n<p>Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>\nsei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T(x)=(x+1)/3<\/annotation><\/semantics><\/math>.\nDie Abbildung erhält das Intervall und hat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q=1/3<\/annotation><\/semantics><\/math>.\nDer Fixpunkt ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.\nBei Start\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_0=0<\/annotation><\/semantics><\/math>\ngilt exakt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mn>3<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_n=(1-3^{-n})/2<\/annotation><\/semantics><\/math>.\nDie a-priori-Schranke ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>3<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3^{-n}/2<\/annotation><\/semantics><\/math>;\nin diesem Beispiel stimmt sie mit dem Fehler überein. Für einen Fehler\nvon höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">10^{-4}<\/annotation><\/semantics><\/math>\ngenügen acht Schritte. Die Grafik zeigt die alternierenden vertikalen\nund horizontalen Schritte der Fixpunktiteration zwischen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y=T(x)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y=x<\/annotation><\/semantics><\/math>\nsowie die Fehlerabnahme.<\/p>\n<p>Die Voraussetzungen sind wesentlich:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>x<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T(x)=x/2<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,1)<\/annotation><\/semantics><\/math>\nist eine Kontraktion ohne Fixpunkt im Raum (nicht vollständig). Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"double-struck\">ℝ<\/mi><annotation encoding=\"application/x-tex\">\\mathbb R<\/annotation><\/semantics><\/math>\nhat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>x<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T(x)=x+1<\/annotation><\/semantics><\/math>\nkeinen Fixpunkt trotz Lipschitz-Konstante 1. Selbst punktweise strikte\nAbstandsverkleinerung reicht nicht: Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>1<\/mn><mo>,<\/mo><mi>∞<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[1,\\infty)<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>x<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T(x)=x+1/x<\/annotation><\/semantics><\/math>\nfür verschiedene\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x,y<\/annotation><\/semantics><\/math>\nstrikt abstandsverkleinernd, weil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>T<\/mi><mi>x<\/mi><mo>−<\/mo><mi>T<\/mi><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|Tx-Ty|=|x-y||1-1/(xy)|&lt;|x-y|<\/annotation><\/semantics><\/math>.\nAber es gibt keinen gemeinsamen Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q&lt;1<\/annotation><\/semantics><\/math>\nund keinen Fixpunkt.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_051_DE.svg\"\nalt=\"Fixpunktiteration und geometrische Fehlerabnahme\" />\n<figcaption aria-hidden=\"true\">Fixpunktiteration und geometrische\nFehlerabnahme<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Anwendung auf Differentialgleichungen<\/h2>\n<p>Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">C([0,1/2])<\/annotation><\/semantics><\/math>\nmit Supremumsnorm definiere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>T<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>+<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">(Tf)(t)=1+\\int_0^t f(s)\\,ds<\/annotation><\/semantics><\/math>.\nDer Operator ist eine Selbstabbildung und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>T<\/mi><mi>f<\/mi><mo>−<\/mo><mi>T<\/mi><mi>g<\/mi><msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>∞<\/mi><\/msub><mo>≤<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>f<\/mi><mo>−<\/mo><mi>g<\/mi><msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>∞<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\|Tf-Tg\\|_\\infty\\le\\tfrac12\\|f-g\\|_\\infty<\/annotation><\/semantics><\/math>.\nDer Fixpunktsatz liefert genau eine stetige Lösung der\nIntegralgleichung. Wegen des Hauptsatzes ist sie differenzierbar und\nerfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=y<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=1<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><msup><mi>e<\/mi><mi>t<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y=e^t<\/annotation><\/semantics><\/math>.\nBei Start\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f_0=1<\/annotation><\/semantics><\/math>\nsind die Iterierten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msubsup><mo>∑<\/mo><mrow><mi>k<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><mi>n<\/mi><\/msubsup><msup><mi>t<\/mi><mi>k<\/mi><\/msup><mi>/<\/mi><mi>k<\/mi><mi>!<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f_n(t)=\\sum_{k=0}^n t^k/k!<\/annotation><\/semantics><\/math>.\nDas folgt durch Induktion und gliedweises Integrieren der endlichen\nSumme. Da\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><msub><mi>f<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>f<\/mi><mn>0<\/mn><\/msub><msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>∞<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\|f_1-f_0\\|_\\infty=1/2<\/annotation><\/semantics><\/math>,\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><msup><mi>e<\/mi><mi>t<\/mi><\/msup><msub><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>∞<\/mi><\/msub><mo>≤<\/mo><msup><mn>2<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\|f_n-e^t\\|_\\infty\\le2^{-n}<\/annotation><\/semantics><\/math>.\nDie tatsächliche Taylorrestschranke ist deutlich besser. Für allgemeine\nPicard-Operatoren benötigt man unter anderem eine geeignete invariante\nFunktionsmenge und eine Lipschitz-Bedingung in der Zustandsvariable; ein\nbeliebiger Zeithorizont ist nicht automatisch eine Kontraktion.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme Fixpunkt und Kontraktionsfaktor von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><mi>x<\/mi><mo>+<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T(x)=0{,}4x+3<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"double-struck\">ℝ<\/mi><annotation encoding=\"application/x-tex\">\\mathbb R<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q=1/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d(x_1,x_0)=2<\/annotation><\/semantics><\/math>:\nWie viele Schritte garantiert die a-priori-Schranke für einen Fehler\nhöchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>01<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}01<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf man bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,1)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>x<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T(x)=x/2<\/annotation><\/semantics><\/math>\nnicht den Fixpunktsatz verwenden?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f_2(t)<\/annotation><\/semantics><\/math>\nfür den Integraloperator aus S5.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Leite aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>T<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mi>δ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">d(x,Tx)\\le\\delta<\/annotation><\/semantics><\/math>\neine garantierte Distanz zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mo>*<\/mo><\/msup><annotation encoding=\"application/x-tex\">x^*<\/annotation><\/semantics><\/math>\nab.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x^*=5<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q=0{,}4<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mo>⋅<\/mo><msup><mn>2<\/mn><mrow><mi>−<\/mi><mi>n<\/mi><\/mrow><\/msup><mo>≤<\/mo><mn>0<\/mn><mo>,<\/mo><mn>01<\/mn><\/mrow><annotation encoding=\"application/x-tex\">4\\cdot2^{-n}\\le0{,}01<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=9<\/annotation><\/semantics><\/math>\ngenügt,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=8<\/annotation><\/semantics><\/math>\nnicht.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Raum ist unvollständig; der Grenzwert 0 liegt außerhalb.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>+<\/mo><mi>t<\/mi><mo>+<\/mo><msup><mi>t<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1+t+t^2/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>T<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>q<\/mi><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d(x,x^*)\\le d(x,Tx)+q d(x,x^*)<\/annotation><\/semantics><\/math>,\ndaher höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>δ<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\delta/(1-q)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.math.utoronto.ca/almut/MAT267/Tutorial-6A.pdf\">University\nof Toronto, MAT267, Tutorial 6<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · p. 1: assumptions, uniqueness,\nexistence, geometric error estimate; PDF text only · Zuletzt abgerufen:\n2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>"};
